SELECT name 
FROM products 
WHERE stock_quantity = 0;

SELECT name, price 
FROM products 
ORDER BY price DESC;

SELECT name, price 
FROM products 
ORDER BY price ASC;

SELECT c.name AS customer_name, o.product_name AS order_product, o.quantity, o.order_date, o.total_price
FROM customers c
JOIN orders o ON c.id = o.customer_id;

SELECT c.email 
FROM customers c 
JOIN orders o ON c.id = o.customer_id;

SELECT DISTINCT c.name, c.email 
FROM customers c
JOIN orders o ON c.id = o.customer_id;

SELECT o.id AS order_id, c.name AS customer_name, o.product_name, o.quantity, o.order_date, o.total_price 
FROM orders o 
JOIN customers c ON o.customer_id = c.id;
